def is_checkerboard(grid):
    total = sum(len(row) for row in grid)
    if total <= 1:
        return True
    rows = len(grid)
    group0 = set()
    group1 = set()
    for r in range(rows):
        row = grid[r]
        for c in range(len(row)):
            v = row[c]
            if (r + c) % 2 == 0:
                group0.add(v)
            else:
                group1.add(v)
    if len(group0) > 1 or len(group1) > 1:
        return False
    if group0 and group1:
        a = next(iter(group0))
        b = next(iter(group1))
        return a != b
    return True

def shift_rows_down(grid, k):
    n = len(grid)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return [row[:] for row in grid]
    return [row[:] for row in grid[-k:]] + [row[:] for row in grid[:-k]]

def parse_kv_pairs(s):
    if s == "":
        return {}
    result = {}
    for part in s.split(";"):
        k, v = part.split("=", 1)
        result[k] = v
    return result

def compare_semver(v1, v2):
    t1 = tuple(int(x) for x in v1.split("."))
    t2 = tuple(int(x) for x in v2.split("."))
    if t1 < t2:
        return -1
    if t1 > t2:
        return 1
    return 0

def increment_semver(version, part):
    major, minor, patch = (int(x) for x in version.split("."))
    if part == "major":
        major += 1
        minor = 0
        patch = 0
    elif part == "minor":
        minor += 1
        patch = 0
    elif part == "patch":
        patch += 1
    return f"{major}.{minor}.{patch}"

