import re

def parse_simple_expr(s):
    m = re.match(r"(\d+)([+\-*/])(\d+)", s)
    a = int(m.group(1))
    op = m.group(2)
    b = int(m.group(3))
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    return a / b

def parse_url_parts(url):
    scheme, rest = url.split("://", 1)
    idx = len(rest)
    for i, ch in enumerate(rest):
        if ch == "/" or ch == "?":
            idx = i
            break
    host = rest[:idx]
    remainder = rest[idx:]
    if remainder.startswith("?"):
        path = ""
        query = remainder[1:]
    elif remainder.startswith("/"):
        if "?" in remainder:
            path, query = remainder.split("?", 1)
        else:
            path = remainder
            query = ""
    else:
        path = ""
        query = ""
    return {"scheme": scheme, "host": host, "path": path, "query": query}
